export function LogoMark({ className = 'h-5 w-5', size, title = 'Mizan' }) {
  const dim = size ? { width: size, height: size } : undefined
  return (
    <svg
      viewBox="40 0 225 220"
      className={size ? undefined : className}
      style={dim}
      role="img"
      aria-label={title}
    >
      {BARRAS}
    </svg>
  )
}

/**
 * Logo completa: barras + a palavra "Mizan" desenhada (não é fonte).
 * A cor da palavra é currentColor: clara no fundo escuro (#f4f2fa), escura no
 * tema claro (#1a0033), definida por quem usa.
 */
export function LogoCompleto({ className = 'h-8 w-auto', title = 'Mizan' }) {
  return (
    <svg viewBox="50 0 916 220" className={className} role="img" aria-label={title} fill="none">
      {BARRAS}
      <path d={PALAVRA} fill="currentColor" />
    </svg>
  )
}

/** Alias: o símbolo é chamado de MizanMark no material de design. */
export const MizanMark = LogoMark

/** Símbolo + wordmark. O wordmark é só a fonte display, peso 700. */
export default function Logo({ size = 28, gap = 10, wordmark = true, className = '', wordClassName = '' }) {
  return (
    <span className={`inline-flex items-center ${className}`} style={{ gap }}>
      <LogoMark size={size} />
      {wordmark && (
        <span
          className={wordClassName}
          style={{
            fontFamily: 'var(--font-display)',
            fontWeight: 700,
            fontSize: size * 1.05,
            letterSpacing: '-0.03em',
            lineHeight: 1,
            color: 'currentColor',
          }}
        >
          Mizan
        </span>
      )}
    </span>
  )
}
